(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let productsPromise,toastTimer;const productMap=new Map();
async function getProducts(){if(!productsPromise)productsPromise=fetch('/products.json').then(r=>{if(!r.ok)throw Error('Каталог недоступен');return r.json()}).then(ps=>{for(const p of ps)productMap.set(p.url,p);return ps});return productsPromise}
function getCart(){try{let c=JSON.parse(localStorage.getItem('steklofurnitura-inquiry')||'[]');return Array.isArray(c)?c.filter(x=>x&&typeof x.url==='string'&&Number.isFinite(x.qty)&&x.qty>0).map(x=>({...x,qty:Math.min(99999,x.qty)})):[]}catch{return[]}}
function saveCart(c){try{localStorage.setItem('steklofurnitura-inquiry',JSON.stringify(c))}catch{toast('Браузер не разрешает сохранять заявку. Включите локальное хранение.');return false}updateCount();return true}
function updateCount(){$$('.cart-count').forEach(el=>el.textContent=getCart().reduce((n,p)=>n+p.qty,0))}
function toast(message){const el=$('.toast');if(!el)return;el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3200)}
function showMenu(id,open){const panel=document.getElementById(id);if(!panel)return;panel.hidden=!open;$$(`[data-toggle="${id}"]`).forEach(b=>b.setAttribute('aria-expanded',String(open)))}
$$('form.search,form.large-search').forEach(form=>form.addEventListener('submit',ev=>{ev.preventDefault();const q=form.querySelector('input[name="q"]').value.trim();location.assign('/search.html?q='+encodeURIComponent(q))}));
document.addEventListener('click',async ev=>{
 const toggle=ev.target.closest('[data-toggle]');if(toggle){const id=toggle.dataset.toggle;const open=document.getElementById(id)?.hidden;['catalog-menu','mobile-nav'].filter(x=>x!==id).forEach(x=>showMenu(x,false));showMenu(id,open);return}
 if(!ev.target.closest('header'))['catalog-menu','mobile-nav'].forEach(id=>showMenu(id,false));
 const add=ev.target.closest('[data-product]');if(add){try{await getProducts();const p=productMap.get(add.dataset.product);if(!p)throw Error('Товар не найден');const input=$('#quantity'),qty=Math.min(99999,Math.max(1,Number(input?.value)||1));if(!Number.isInteger(qty)){toast('Укажите целое количество');return}const c=getCart(),existing=c.find(x=>x.url===p.url);if(existing)existing.qty=Math.min(99999,existing.qty+qty);else c.push({url:p.url,qty});if(saveCart(c))toast('Товар добавлен в заявку')}catch{toast('Не удалось загрузить товар. Попробуйте ещё раз.')}return}
 const qty=ev.target.closest('[data-qty]');if(qty){const input=$('input',qty.parentElement);const value=Math.min(99999,Math.max(1,(Number(input.value)||1)+Number(qty.dataset.qty)));input.value=value;if(qty.closest('[data-cart-url]'))updateRow(qty.closest('[data-cart-url]').dataset.cartUrl,value);return}
 const remove=ev.target.closest('[data-remove]');if(remove){saveCart(getCart().filter(x=>x.url!==remove.dataset.remove));renderCart();return}
 const thumb=ev.target.closest('[data-image]');if(thumb&&$('#detail-photo')){$('#detail-photo').src=thumb.dataset.image;return}
 const lb=ev.target.closest('[data-lightbox]');if(lb){ev.preventDefault();const d=document.createElement('dialog');d.className='lightbox';const img=document.createElement('img');img.src=lb.href;img.alt=$('img',lb)?.alt||'Изображение';const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Закрыть изображение');close.addEventListener('click',()=>d.close());d.append(img,close);document.body.append(d);d.addEventListener('click',x=>{if(x.target===d)d.close()});d.addEventListener('close',()=>d.remove());d.showModal();return}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')['catalog-menu','mobile-nav'].forEach(id=>showMenu(id,false))});
function updateRow(url,value){const c=getCart(),p=c.find(x=>x.url===url);if(p){p.qty=Math.min(99999,Math.max(1,Math.round(Number(value)||1)));saveCart(c)}}
document.addEventListener('change',ev=>{if(ev.target.matches('[data-cart-url] input,#quantity')){ev.target.value=Math.min(99999,Math.max(1,Math.round(Number(ev.target.value)||1)));if(ev.target.matches('[data-cart-url] input'))updateRow(ev.target.closest('[data-cart-url]').dataset.cartUrl,ev.target.value)}});
function card(p){return `<article class="product-card"><a class="product-photo" href="${e(p.url)}"><img src="${e(p.image)}" alt="${e(p.name)}" loading="lazy"></a><div class="product-content"><span class="product-article">${e(p.article)}</span><h3><a href="${e(p.url)}">${e(p.name)}</a></h3><p class="finish">${e(p.finish)}</p><div class="product-stock">${p.stock?'<i></i>'+e(p.stock):''}</div><div class="product-bottom"><span class="product-price">${e(p.price||'Цену уточняйте')}</span><button class="add-product" data-product="${e(p.url)}" aria-label="Добавить в заявку"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 5v14M5 12h14"/></svg></button></div></div></article>`}
async function search(){const results=$('#search-results');if(!results)return;const q=(new URLSearchParams(location.search).get('q')||'').trim();$('#search-query').value=q;const summary=$('#search-summary');if(!q){summary.textContent='Найдите фурнитуру по названию, артикулу, бренду или отделке.';return}summary.textContent='Ищем в каталоге…';try{const ps=await getProducts();const norm=s=>s.toLocaleLowerCase('ru').replace(/[\s\-–хx×]/g,'');const words=q.split(/\s+/).filter(Boolean).map(norm);const matches=ps.filter(p=>words.every(w=>norm([p.name,p.article,p.finish,p.url].join(' ')).includes(w)));summary.textContent=`По запросу «${q}» найдено товаров: ${matches.length}`;results.innerHTML=matches.length?matches.map(card).join(''):'<div class="empty-state"><h2>Ничего не найдено</h2><p>Попробуйте другой артикул или более короткое название.</p><a class="button" href="/catalog.html">Открыть каталог</a></div>'}catch{summary.textContent='Не удалось загрузить каталог. Обновите страницу.'}}
async function renderCart(){const root=$('#cart-content');if(!root)return;const c=getCart(),form=$('#inquiry-form');if(!c.length){root.innerHTML='<div class="empty-state"><h2>Ваша заявка пока пуста</h2><p>Добавьте товары из каталога, чтобы подготовить запрос менеджеру.</p><a class="button" href="/catalog.html">Перейти в каталог →</a></div>';form.hidden=true;return}try{await getProducts();root.innerHTML=c.map(x=>{const p=productMap.get(x.url);if(!p)return'';return `<div class="cart-row" data-cart-url="${e(x.url)}"><img src="${e(p.image)}" alt="${e(p.name)}"><div><h3><a href="${e(p.url)}">${e(p.name)}</a></h3><p>${e(p.article)} · ${e(p.finish)}</p></div><div class="qty"><button data-qty="-1" aria-label="Уменьшить количество">−</button><input type="number" min="1" max="99999" value="${x.qty}" aria-label="Количество"><button data-qty="1" aria-label="Увеличить количество">+</button></div><button class="cart-remove" data-remove="${e(x.url)}" aria-label="Убрать из заявки">×</button></div>`}).join('');form.hidden=false}catch{root.textContent='Не удалось загрузить товары. Обновите страницу.'}}
function inquiryText(){const form=$('#inquiry');const f=new FormData(form);return ['Здравствуйте! Прошу уточнить стоимость и наличие фурнитуры.','',...getCart().map((x,i)=>{const p=productMap.get(x.url);return p?`${i+1}. ${p.name}\nАрт.: ${p.article}\nОтделка: ${p.finish}\nКоличество: ${x.qty} ${p.unit||'шт.'}\nСсылка: https://www.steklofurnitura.by${p.url}`:''}),'',`Имя: ${f.get('name')}`,`Телефон: ${f.get('phone')}`,`Комментарий: ${f.get('comment')||''}`].join('\n')}
$('#inquiry')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);const mail=f.get('manager');const url=`mailto:${encodeURIComponent(mail)}?subject=${encodeURIComponent('Заявка на подбор фурнитуры')}&body=${encodeURIComponent(inquiryText())}`;if(url.length>7500){toast('Заявка слишком большая для почтовой ссылки. Скопируйте список и отправьте его менеджеру.');return}location.href=url;toast('Заявка подготовлена. Отправьте письмо в почтовой программе.')});
$('#copy-inquiry')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(inquiryText());toast('Список скопирован')}catch{toast('Не удалось скопировать. Выделите товары на странице и скопируйте вручную.')}});
$('#sort-products')?.addEventListener('change',async ev=>{const grid=$('.catalog-products');if(!grid)return;const all=$$('.product-card',grid);all.forEach((c,i)=>{if(!c.dataset.order)c.dataset.order=i});const key=ev.target.value;all.sort((a,b)=>key==='default'?Number(a.dataset.order)-Number(b.dataset.order):(key==='name'?$('h3',a).textContent:$(' .product-article',a).textContent).localeCompare(key==='name'?$('h3',b).textContent:$('.product-article',b).textContent,'ru',{numeric:true}));grid.append(...all)});
window.addEventListener('storage',()=>{updateCount();renderCart()});updateCount();search();renderCart();
})();
